def longest_subarray(N, arr):
    count_map = {}
    start = 0
    max_length = 0

    for end in range(N):
        if arr[end] in count_map:
            count_map[arr[end]] += 1
        else:
            count_map[arr[end]] = 1

        while count_map[arr[end]] > 2:
            count_map[arr[start]] -= 1
            if count_map[arr[start]] == 0:
                del count_map[arr[start]]
            start += 1

        if all(count == 2 for count in count_map.values()):
            max_length = max(max_length, end - start + 1)

    return max_length

